from pathlib import Path
import json,hashlib,subprocess,collections,datetime,re
ROOT=Path('/workspace/scratch/f8f9b9cbce53/reaudit/source')
OUT=Path('/workspace/scratch/f8f9b9cbce53/reaudit/reports/inbox')
OLD=Path('/workspace/scratch/8b95153002da/reconciliation/docs/reconciliation')
SHA='da307ba5626dce892f0b37cb6762463f55d14a96'
BASE='2e7cf81c6c4d6ae9942e4a5d7fbc1ddb06788ab6'
INTEGRITY=json.loads((ROOT.parent/'source-integrity.json').read_text())
EXPECTED_BLOBS={row['path']:row['git_blob_sha'] for row in INTEGRITY['files']}
OBSERVED_HEAD=subprocess.check_output(['git','-C',str(ROOT),'rev-parse','HEAD'],text=True).strip()
assert OBSERVED_HEAD==SHA==INTEGRITY['head_sha'], 'source HEAD mismatch'
def checked_source_bytes(path):
 raw=(ROOT/path).read_bytes()
 observed=hashlib.sha1(b'blob '+str(len(raw)).encode()+b'\0'+raw).hexdigest()
 assert EXPECTED_BLOBS.get(path)==observed, ('source blob mismatch',path)
 return raw
PROBES=json.loads((OUT/'probes/results.json').read_text())
PASS2_PROBES=json.loads((OUT/'probes/pass2/results.json').read_text())
PASS3_PROBES=json.loads((OUT/'probes/pass3/results.json').read_text())
PASS4_PROBES=json.loads((OUT/'probes/pass4/results.json').read_text())
PASS5_PROBES=json.loads((OUT/'probes/pass5/results.json').read_text())
F=[]
def ev(path,start,end,claim):
 raw=checked_source_bytes(path); n=len(raw.decode().splitlines()); assert 1<=start<=end<=n,(path,start,end,n)
 return {'path':path,'absolute_path':str(ROOT/path),'line_start':start,'line_end':end,'source_sha':SHA,'blob_sha':hashlib.sha1(b'blob '+str(len(raw)).encode()+b'\0'+raw).hexdigest(),'claim':claim}
